+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const CACHE_DIR = ".cache";
 const store = new Map<string, Entry>();

+const ensureCacheDir = (): void => {
+  if (!fs.existsSync(CACHE_DIR)) {
+    fs.mkdirSync(CACHE_DIR, { recursive: true });
+  }
+};
+
+const getCachePath = (key: string): string => {
+  return path.join(CACHE_DIR, encodeURIComponent(key));
+};
+
+const loadFromDisk = (key: string): Entry | null => {
+  const filePath = getCachePath(key);
+  try {
+    if (fs.existsSync(filePath)) {
+      const data = fs.readFileSync(filePath, "utf-8");
+      return JSON.parse(data);
+    }
+  } catch {
+    // Ignore errors reading corrupted cache files
+  }
+  return null;
+};
+
+const saveToDisk = (key: string, entry: Entry): void => {
+  const filePath = getCachePath(key);
+  try {
+    fs.writeFileSync(filePath, JSON.stringify(entry), "utf-8");
+  } catch {
+    // Ignore errors writing to cache (in-memory cache still works)
+  }
+};
+
+const deleteFromDisk = (key: string): void => {
+  const filePath = getCachePath(key);
+  try {
+    if (fs.existsSync(filePath)) {
+      fs.unlinkSync(filePath);
+    }
+  } catch {
+    // Ignore errors deleting cache file
+  }
+};
+
 export const put = (key: string, value: string, ttlMs: number): void => {
-  store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  ensureCacheDir();
+  const entry = { value, expiresAt: Date.now() + ttlMs };
+  store.set(key, entry);
+  saveToDisk(key, entry);
 };

 export const get = (key: string): string | null => {
-  const entry = store.get(key);
+  let entry = store.get(key);
+
+  if (entry === undefined) {
+    entry = loadFromDisk(key);
+    if (entry !== null) {
+      store.set(key, entry);
+    }
+  }
+
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    deleteFromDisk(key);
     return null;
   }
   return entry.value;
